import{z as B,x as A,o as t,c as p,q as n,j as s,D as r,d as E,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"多元已实现协方差","description":"","frontmatter":{"title":"多元已实现协方差","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/realized-covariance.md","filePath":"quant/realized-covariance.md","lastUpdated":1791413859000}'),d={name:"quant/realized-covariance.md"};function h(C,a,m,u,c,f){const i=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="多元已实现协方差" tabindex="-1">多元已实现协方差 <a class="header-anchor" href="#多元已实现协方差" aria-label="Permalink to &quot;多元已实现协方差&quot;">​</a></h1><div class="epigraph"><p>无噪声、同步观测时，日内收益外积之和收敛到积分协变差；异步与噪声会把同一加总拉向零或拉向噪声交叉项，必须先声明对时与降噪。</p><footer>—— Barndorff-Nielsen and Shephard, Econometric Analysis of Realized Covariation, Econometrica, 2004</footer></div><p><a href="/quant/tsrv">TSRV</a> 修好了一元 \\(IV\\)。组合、\\([X,Y]\\)、对冲比需要矩阵。Barndorff-Nielsen 与 Shephard 给出无噪声同步下已实现协方差 \\(\\sum r_i r_i^\\top\\to_p \\int\\sigma_u\\sigma_u^\\top du\\) 的渐近理论，并与已实现方差同一套幂变差语言。实务立刻碰到两件事：股票不同步成交（<a href="/quant/epps-effect">Epps</a>），以及噪声交叉。本课缺口：把 <strong>BN–S 的对象</strong>写清，并把偏差来源分类；<a href="/quant/hayashi-yoshida">Hayashi–Yoshida</a> 已给不同步的一种估计量。下一课把矩阵收成已实现 \\(\\beta\\)；刷新时间课专门对付同步规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(d\\) 维对数价格 \\(X\\)，积分协变差矩阵 \\(\\Sigma=\\int_0^1 \\sigma_u\\sigma_u^\\top du\\)。同步网格、无噪声、无跳（或跳计入）时</p> \\[\\mathrm{RCOV}=\\sum_{i=1}^{n}\\Delta X_i\\Delta X_i^\\top \\ \\xrightarrow{p}\\ \\Sigma+[{\\mathrm{跳的外积}}]. \\]<p>观测是不同步的 \\(Y=X+\\varepsilon\\)。Previous-tick 到公共格子再做 RCOV，密格子上大量零乘积，表观相关下降——Epps。噪声使对角像一元那样爆，非对角若噪声独立则主要加方差，若共同微观结构则偏。问题是：对象是 \\(\\Sigma\\) 的哪一部分（含不含跳），以及同步规则是 HY、刷新时间还是降频到五分钟。</p><p><span class="marginnote">直觉类比看 Epps：两只股票各记一本流水账，一只每秒成交、另一只十分钟才动一次价——逐秒对账时大量格子是「一条动了另一条没动」的零，算出的同步性自然偏低。不是它们不共动，是你的钟太细：采样越密，「没对上拍」的格子越多，相关被越拉越向零。</span></p><p>Andersen、Bollerslev、Diebold、Labys 的经验已实现协方差是后续资产定价与宏观–金融的数据输入；计量上必须带着偏差清单用。</p><h3 id="正定性" tabindex="-1">正定性 <a class="header-anchor" href="#正定性" aria-label="Permalink to &quot;正定性&quot;">​</a></h3><p>逐元 HY 或逐元核，拼起来的矩阵可以不正定。多元已实现核（Barndorff-Nielsen, Hansen, Lunde, Shephard）在刷新时间网格上对向量收益做核，保持半正定构造。工程上：要么整向量一套核，要么对不正定结果做投影（特征值截断），并声明。组合优化对最小特征值敏感，假的负相关会变成假对冲。</p><p><span class="marginnote">五分钟 previous-tick 矩阵是最常见的正定（外积和半正定）折中。它牺牲高频分辨率，换可复现与正定。要更高频，就要付同步与核的复杂度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>同步降频。</strong> 公共五分钟，previous-tick，外积和。隔夜外积单独。适合横截面、HAR 式预测。</p><p><strong>HY。</strong> 二元相交增量，无公共格。噪声脆弱；多元 \\(d\\gt 2\\) 要两两算再拼，正定性不保证。适合配对、期现。</p><p><strong>刷新时间 + 核。</strong> 所有资产都更新后记一格，再多元核。丢快资产在等待期间的成交。适合要半正定、要噪声修正的中等 \\(d\\)。</p><p><strong>跳跃。</strong> 门限或双幂次协变差估连续 \\(\\Sigma\\)；共跳外积是另一对象（新闻课）。先写要连续相关还是总协变差。</p><h3 id="预测与损失" tabindex="-1">预测与损失 <a class="header-anchor" href="#预测与损失" aria-label="Permalink to &quot;预测与损失&quot;">​</a></h3><p>日频 \\(H_t\\) 的预测可用已实现协方差的 HAR（Chiriac–Voev 一类）或 Wishart。评估用多元 QLIKE，代理必须与训练同一同步规则，否则在比较同步偏差。接 <a href="/quant/qlike-vol-forecast-eval">QLIKE</a> 纪律。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同步无噪声时，外积和是二次协变差的黎曼和，BN–S 给出稳定收敛与渐近混合正态。异步的机制是零填充或陈旧价格，共同 \\(d\\langle X^i,X^j\\rangle\\) 被漏记。噪声的机制与一元相同，交叉项 \\(E[\\Delta\\varepsilon^i\\Delta\\varepsilon^j]\\) 在独立时近零。HY 用重叠指示把漏记补回，但不减独立噪声的方差膨胀。</p><p><span class="marginnote">数字实例看外积：某五分钟格，股票 \\(i\\) 涨 \\(0.2\\%\\)、股票 \\(j\\) 跌 \\(0.1\\%\\)，这一格对外积和的贡献是 \\(0.002\\times(-0.001)=-2\\times10^{-6}\\)——负号说明这一格两者反向。把全天 78 格的外积逐格加总成矩阵，就是当天的已实现协方差；「协方差是外积之和」说的就是这个累加。</span></p>',22)),(t(),s(l,null,{default:r(()=>[o(i,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%AB%98%E9%A2%91%E7%9B%B8%E5%85%B3%E5%BC%82%E5%B8%B8%E4%BD%8E%22%5D%20--%3E%20B%7B%22%E9%87%87%E6%A0%B7%E8%B6%8A%E5%AF%86%E8%B6%8A%E4%BD%8E%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22Epps%EF%BC%9A%E9%9B%B6%E5%A1%AB%E5%85%85%E6%BC%8F%E8%AE%B0%E5%85%B1%E5%90%8C%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%8D%A2%E5%90%8C%E6%AD%A5%E8%A7%84%E5%88%99%EF%BC%9A%E5%88%B7%E6%96%B0%E6%97%B6%E9%97%B4%E6%88%96%20HY%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20E%7B%22%E5%AF%B9%E8%A7%92%E6%98%AF%E5%90%A6%E7%88%86%E7%82%B8%EF%BC%9F%22%7D%0A%20%20E%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22%E5%99%AA%E5%A3%B0%EF%BC%9A%E5%85%88%E9%99%8D%E5%99%AA%E5%86%8D%E5%8F%96%E4%BA%A4%E5%8F%89%E9%A1%B9%22%5D%0A%20%20E%20--%3E%7C%22%E5%90%A6%22%7C%20G%7B%22%E6%9C%80%E5%B0%8F%E7%89%B9%E5%BE%81%E5%80%BC%E5%B0%8F%E4%BA%8E%E9%9B%B6%EF%BC%9F%22%7D%0A%20%20G%20--%3E%7C%22%E6%98%AF%22%7C%20H%5B%22%E9%80%90%E5%85%83%E6%8B%BC%E6%8E%A5%E5%A4%B1%E6%AD%A3%E5%AE%9A%EF%BC%9A%E5%90%91%E9%87%8F%E6%A0%B8%E6%88%96%E6%8A%95%E5%BD%B1%22%5D%0A%20%20G%20--%3E%7C%22%E5%90%A6%22%7C%20I%5B%22%E6%A3%80%E6%9F%A5%E5%85%B1%E8%B7%B3%E4%B8%8E%E9%9A%94%E5%A4%9C%E5%A4%96%E7%A7%AF%E5%8F%A3%E5%BE%84%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p><span class="marginnote">这张图回答「算出来的矩阵哪里坏了」的诊断问题，与文末「同步规则怎么选」的图分工不同。常见误区：初学者容易以为「逐个算对的元素拼起来一定对」——不正定恰恰是拼出来的病：假的负相关会变成假对冲，组合优化据此建仓，亏掉的是真钱。</span></p><p>Epps 随采样变密而加剧，是同步规则的函数，不是经济相关消失。把分钟相关当「高频相关真的低」去做日频对冲，会在日频上暴露共同风险。</p><p><span class="marginnote">维数 \\(d\\) 大时，即使五分钟，\\(n\\approx 78\\)，\\(d=50\\) 的矩阵噪声极大，须因子或收缩——波动因子课在已实现矩阵上同样适用。</span></p><h3 id="到已实现-beta-的交接" tabindex="-1">到已实现 beta 的交接 <a class="header-anchor" href="#到已实现-beta-的交接" aria-label="Permalink to &quot;到已实现 beta 的交接&quot;">​</a></h3><p>\\(\\beta^{ij}=\\Sigma^{ij}/\\Sigma^{jj}\\)。分子分母须同一同步与噪声处理，否则 \\(\\beta\\) 系统偏差。下一课专门写这个比。不要用日 \\(\\beta\\) 与高频 \\(\\beta\\) 不加声明地混用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(d\\) 大、流动性差异大，刷新时间被最慢的腿决定，矩阵变成「慢时钟」。应分组（流动性桶）或 HY 配对。缺测、停牌让刷新卡死，须剔除或插值政策。</p><p>工程：研究默认五分钟 RCOV；配对 HY；要噪声修正的向量用刷新+核。报告同步规则与是否投影正定。不要对 tick 未对齐外积和当 \\(\\Sigma\\)。不要用 RCOV 最小特征值去做无约束最小方差组合而不收缩。下一课：实现 beta。</p>',8)),(t(),s(l,null,{default:r(()=>[o(i,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%A4%9A%E8%B5%84%E4%BA%A7%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20SYNC%7B%22%E5%90%8C%E6%AD%A5%E8%A7%84%E5%88%99%22%7D%0A%20%20SYNC%20--%3E%7C%E9%99%8D%E9%A2%91%20previous-tick%7C%20RC%5B%22%E5%A4%96%E7%A7%AF%E5%92%8C%20RCOV%22%5D%0A%20%20SYNC%20--%3E%7C%E7%9B%B8%E4%BA%A4%E5%A2%9E%E9%87%8F%7C%20HY%5B%22Hayashi-Yoshida%22%5D%0A%20%20SYNC%20--%3E%7C%E9%83%BD%E6%9B%B4%E6%96%B0%E6%89%8D%E8%AE%B0%E4%B8%80%E6%A0%BC%7C%20RT%5B%22%E5%88%B7%E6%96%B0%E6%97%B6%E9%97%B4%20%2B%20%E6%A0%B8%22%5D%0A%20%20RC%20--%3E%20S%5B%22%E7%A7%AF%E5%88%86%E5%8D%8F%E5%8F%98%E5%B7%AE%20%CE%A3%22%5D%0A%20%20HY%20--%3E%20S%0A%20%20RT%20--%3E%20S%0A%20%20S%20--%3E%20BETA%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%B7%B2%E5%AE%9E%E7%8E%B0%20%CE%B2%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[E("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"同步无噪声时，已实现协方差外积和一致于积分协变差（BN–S）。"),e("li",null,"异步造成 Epps 向下偏；噪声炸对角、污染交叉；须选 HY、降频或刷新+核。"),e("li",null,"逐元估计会失正定；向量核或特征值投影要声明。"),e("li",null,"预测评估与代理必须同一同步规则。"),e("li",null,[E("出处：Barndorff-Nielsen and Shephard, "),e("em",null,"Econometrica"),E(", 2004；经验已实现协方差见 Andersen, Bollerslev, Diebold and Labys；多元核见 Barndorff-Nielsen, Hansen, Lunde and Shephard。")])],-1))])}const g=B(d,[["render",h]]);export{_ as __pageData,g as default};
